/**
 * Known custodial / exchange hot-wallet addresses (KAN-69).
 *
 * A pooled exchange wallet holds many customers' funds, so tracking it by address would
 * import a balance that isn't the user's. Add Wallet rejects these and points the user
 * to a manual crypto holding instead.
 *
 * The list lives in custodialAddresses.json (generated by `npm run denylist:update` from
 * published proof-of-reserves lists plus custodialAddresses.manual.json). Addresses only —
 * no secrets. Per-user deposit addresses (Nexo, GoMining, exchanges) are unique and can't
 * be listed; the Add Wallet copy and the empty-wallet warning cover those.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  WALLET_NETWORKS,
  normaliseBitcoinAddress,
  normaliseEvmAddress,
  normaliseSolanaAddress,
  type WalletFamily,
  type WalletNetwork,
} from './walletAddress.ts';

export type CustodialEntry = {
  family: WalletFamily;
  address: string;
  custodian: string;
  source: string;
};

export type CustodialFile = {
  updatedAt: string;
  sources: Record<string, { url: string; fetchedAt: string }>;
  addresses: CustodialEntry[];
};

const DIR = path.dirname(fileURLToPath(import.meta.url));
export const DENYLIST_PATH = path.join(DIR, 'custodialAddresses.json');

/**
 * Canonical lookup key. EVM is case-insensitive (one entry covers every EVM network,
 * since an exchange's EOA is the same address on Ethereum, Polygon, Base and Arbitrum);
 * bech32 is lowercased by the normaliser; base58 (legacy BTC, Solana) is case-sensitive.
 * Returns null when the address isn't valid for the family.
 */
export function custodialKey(family: WalletFamily, address: string): string | null {
  const a = address.trim();
  const normalised =
    family === 'evm'
      ? normaliseEvmAddress(a)?.toLowerCase()
      : family === 'bitcoin'
        ? normaliseBitcoinAddress(a)
        : normaliseSolanaAddress(a);
  return normalised ? `${family}:${normalised}` : null;
}

/** Build the lookup map. Throws on an invalid entry so a typo fails tests, not silently. */
export function buildDenylist(entries: CustodialEntry[]): Map<string, CustodialEntry> {
  const map = new Map<string, CustodialEntry>();
  for (const e of entries) {
    const key = custodialKey(e.family, e.address);
    if (!key) throw new Error(`custodial denylist: invalid ${e.family} address ${e.address} (${e.custodian})`);
    if (!e.custodian?.trim()) throw new Error(`custodial denylist: ${e.address} has no custodian`);
    map.set(key, e);
  }
  return map;
}

let cached: Map<string, CustodialEntry> | null = null;

function denylist(): Map<string, CustodialEntry> {
  if (!cached) {
    const file = JSON.parse(fs.readFileSync(DENYLIST_PATH, 'utf8')) as CustodialFile;
    cached = buildDenylist(file.addresses);
  }
  return cached;
}

/** The custodian that owns this address, or null. `address` should already be validated. */
export function findCustodialAddress(
  network: WalletNetwork,
  address: string,
  list: Map<string, CustodialEntry> = denylist(),
): CustodialEntry | null {
  const key = custodialKey(WALLET_NETWORKS[network].family, address);
  return (key && list.get(key)) || null;
}

export function custodialMessage(entry: CustodialEntry): string {
  return (
    `This address belongs to ${entry.custodian}, which holds many customers' funds in one wallet, ` +
    `so it can't show your balance. Add crypto you keep on an exchange or app (Nexo, GoMining, ` +
    `Binance…) as a manual crypto holding instead. Wallet tracking is only for wallets you control.`
  );
}
